CREATE TABLE IF NOT EXISTS legacy_bank_account_bindings (
 id INTEGER PRIMARY KEY, bank_account_id INTEGER NOT NULL UNIQUE REFERENCES bank_accounts(id), ledger_account_no TEXT NOT NULL REFERENCES accounts(account_no), cutoff TEXT NOT NULL, statement_transaction_id INTEGER NOT NULL REFERENCES bank_transactions(id), statement_transaction_hash TEXT NOT NULL CHECK(length(statement_transaction_hash)=64), statement_balance_ore TEXT NOT NULL, ledger_balance_ore TEXT NOT NULL, ledger_head_hash TEXT, audit_head_hash TEXT NOT NULL CHECK(length(audit_head_hash)=64), plan_hash TEXT NOT NULL UNIQUE CHECK(length(plan_hash)=64), idempotency_key TEXT NOT NULL CHECK(length(trim(idempotency_key)) BETWEEN 1 AND 128), actor TEXT NOT NULL, principal_kind TEXT NOT NULL CHECK(principal_kind IN ('user','service-account')), principal_subject_id TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(principal_kind,principal_subject_id,idempotency_key)
);
CREATE TABLE IF NOT EXISTS legacy_payable_payment_backfills (
 id INTEGER PRIMARY KEY, purchase_journal_entry_id INTEGER NOT NULL UNIQUE REFERENCES journal_entries(id), payment_journal_entry_id INTEGER NOT NULL UNIQUE REFERENCES journal_entries(id), document_id INTEGER NOT NULL UNIQUE REFERENCES documents(id), bank_transaction_id INTEGER NOT NULL UNIQUE REFERENCES bank_transactions(id), payable_id INTEGER NOT NULL UNIQUE REFERENCES payables(id), payment_id INTEGER NOT NULL UNIQUE REFERENCES payable_payments(id), purchase_journal_hash TEXT NOT NULL CHECK(length(purchase_journal_hash)=64), payment_journal_hash TEXT NOT NULL CHECK(length(payment_journal_hash)=64), document_hash TEXT NOT NULL CHECK(length(document_hash)=64), bank_transaction_hash TEXT NOT NULL CHECK(length(bank_transaction_hash)=64), plan_hash TEXT NOT NULL UNIQUE CHECK(length(plan_hash)=64), ledger_head_hash TEXT, audit_head_hash TEXT NOT NULL CHECK(length(audit_head_hash)=64), idempotency_key TEXT NOT NULL CHECK(length(trim(idempotency_key)) BETWEEN 1 AND 128), actor TEXT NOT NULL, principal_kind TEXT NOT NULL CHECK(principal_kind IN ('user','service-account')), principal_subject_id TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(principal_kind,principal_subject_id,idempotency_key)
);
CREATE TRIGGER IF NOT EXISTS legacy_bank_account_bindings_no_update BEFORE UPDATE ON legacy_bank_account_bindings BEGIN SELECT RAISE(ABORT,'legacy bank bindings are append-only'); END;
CREATE TRIGGER IF NOT EXISTS legacy_bank_account_bindings_no_delete BEFORE DELETE ON legacy_bank_account_bindings BEGIN SELECT RAISE(ABORT,'legacy bank bindings are append-only'); END;
CREATE TRIGGER IF NOT EXISTS legacy_payable_payment_backfills_no_update BEFORE UPDATE ON legacy_payable_payment_backfills BEGIN SELECT RAISE(ABORT,'legacy payable payment backfills are append-only'); END;
CREATE TRIGGER IF NOT EXISTS legacy_payable_payment_backfills_no_delete BEFORE DELETE ON legacy_payable_payment_backfills BEGIN SELECT RAISE(ABORT,'legacy payable payment backfills are append-only'); END;
